package com.example.mimowidget;
import android.app.*;import android.app.job.*;import android.appwidget.*;import android.content.*;import android.os.*;import android.webkit.CookieManager;import android.widget.RemoteViews;import org.json.*;import java.net.*;import java.io.*;import java.text.*;import java.util.*;
public class Data {
 static final String URL="https://platform.xiaomimimo.com/console/plan-manage";static final String API="https://platform.xiaomimimo.com/api/v1/tokenPlan/usage";
 static void schedule(Context c){try{JobScheduler js=(JobScheduler)c.getSystemService(Context.JOB_SCHEDULER_SERVICE);js.schedule(new JobInfo.Builder(18761,new ComponentName(c,RefreshJob.class)).setRequiredNetworkType(JobInfo.NETWORK_TYPE_ANY).setPeriodic(1800000).setPersisted(true).build());}catch(Exception ignored){}}
 static String refresh(Context c){String message; try{String cookie=CookieManager.getInstance().getCookie(API);if(cookie==null||cookie.isEmpty())throw new Exception("Войдите в аккаунт Xiaomi"); HttpsURLConnectionDummy unused=null; HttpURLConnection conn=(HttpURLConnection)new URL(API).openConnection();conn.setInstanceFollowRedirects(false);conn.setConnectTimeout(15000);conn.setReadTimeout(15000);conn.setRequestProperty("Cookie",cookie);conn.setRequestProperty("Accept","application/json");conn.setRequestProperty("User-Agent","Mozilla/5.0 Android MiMoWidget"); int code=conn.getResponseCode();if(code==401||code==403||code>=300&&code<400)throw new Exception("Сессия истекла — войдите снова");if(code!=200)throw new Exception("Ошибка сервера: "+code); ByteArrayOutputStream out=new ByteArrayOutputStream();try(InputStream in=conn.getInputStream()){byte[] b=new byte[4096];int n;while((n=in.read(b))!=-1){out.write(b,0,n);if(out.size()>1000000)throw new Exception("Ответ слишком большой");}}JSONObject json=new JSONObject(out.toString("UTF-8"));if(json.optInt("code",0)==401)throw new Exception("Сессия истекла — войдите снова");JSONObject data=json.getJSONObject("data");JSONArray items=data.getJSONObject("usage").getJSONArray("items");JSONObject item=null;for(int i=0;i<items.length();i++){JSONObject x=items.optJSONObject(i);if(x!=null && (x.toString().contains("plan_total_token"))){item=x;break;}}if(item==null)throw new Exception("Показатель Token Plan не найден");JSONObject val=item.optJSONObject("plan_total_token");if(val==null)val=item;long used=parse(val,"used"), limit=parse(val,"limit");if(limit<=0)throw new Exception("Лимит Token Plan не найден");long now=System.currentTimeMillis();c.getSharedPreferences("data",0).edit().putLong("used",used).putLong("limit",limit).putLong("time",now).putString("error","").apply();message="Данные обновлены";}catch(Exception e){message=e.getMessage()==null?"Не удалось обновить данные":e.getMessage();c.getSharedPreferences("data",0).edit().putString("error",message).apply();}update(c);return message;}
 static long parse(JSONObject x,String k)throws Exception{String s=x.getString(k).replace(",","").replace(" ","");return new java.math.BigDecimal(s).longValue();}
 static void update(Context c){android.content.SharedPreferences p=c.getSharedPreferences("data",0);long u=p.getLong("used",0),l=p.getLong("limit",0),t=p.getLong("time",0);String err=p.getString("error","");RemoteViews v=new RemoteViews(c.getPackageName(),com.mimo.tokenwidget.R.layout.widget);NumberFormat f=NumberFormat.getIntegerInstance(new Locale("ru","RU"));v.setTextViewText(com.mimo.tokenwidget.R.id.usage,l>0?"Использовано: "+f.format(u)+" / "+f.format(l)+"\nОсталось: "+f.format(Math.max(0,l-u)):"Откройте приложение для входа");v.setProgressBar(com.mimo.tokenwidget.R.id.progress,100,l>0?(int)Math.min(100,u*100.0/l):0,false);String date=t>0?"Обновлено: "+new SimpleDateFormat("dd.MM HH:mm",new Locale("ru")).format(new Date(t)):"Нет данных";v.setTextViewText(com.mimo.tokenwidget.R.id.status,err.isEmpty()?date:date+" · "+err);Intent i=new Intent(c,MainActivity.class);PendingIntent pi=PendingIntent.getActivity(c,0,i,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);v.setOnClickPendingIntent(com.mimo.tokenwidget.R.id.root,pi);Intent refresh=new Intent(c,Widget.class).setAction(Widget.REFRESH);PendingIntent refreshPi=PendingIntent.getBroadcast(c,1,refresh,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);v.setOnClickPendingIntent(com.mimo.tokenwidget.R.id.refresh,refreshPi);AppWidgetManager am=AppWidgetManager.getInstance(c);am.updateAppWidget(new ComponentName(c,Widget.class),v);}
 static class HttpsURLConnectionDummy{}
}
